import assert from "node:assert/strict";
import { test } from "node:test";
import { signToken, verifyToken } from "../src/token.js";

const KEY = "test-key";
const claims = { agent: "nova", jira: "RH-1", run: "run-1", exp: 2_000_000_000 };

test("a signed token verifies and returns its claims", () => {
  assert.deepEqual(verifyToken(signToken(claims, KEY), KEY), claims);
});
test("a token signed with another key is refused", () => {
  assert.equal(verifyToken(signToken(claims, "other"), KEY), null);
});
test("changing a claim breaks the signature", () => {
  const [, mac] = signToken(claims, KEY).split(".");
  const forged = Buffer.from(JSON.stringify({ ...claims, agent: "admin" })).toString("base64url");
  assert.equal(verifyToken(`${forged}.${mac}`, KEY), null);
});
test("an expired token is refused", () => {
  const now = (claims.exp + 1) * 1000; // a fake clock: one second after exp
  assert.equal(verifyToken(signToken(claims, KEY), KEY, now), null);
});

import assert from "node:assert/strict";
import type { AddressInfo } from "node:net";
import { after, before, test } from "node:test";
import { newCapability } from "../src/capability.js";
import { createApp } from "../src/server.js";

const { capability, digest } = newCapability();
const server = createApp(digest);
const auth = { authorization: `Bearer ${capability}` };
let base = "";
before(async () => {
  await new Promise<void>((done) => server.listen(0, done)); // port 0: the OS picks a free port
  base = `http://localhost:${(server.address() as AddressInfo).port}`;
});
after(() => server.close());
test("GET /health answers without a capability", async () => {
  assert.equal((await fetch(`${base}/health`)).status, 200);
});
test("a missing capability gets 401", async () => {
  assert.equal((await fetch(`${base}/v1/notes`)).status, 401);
});
test("a body over 1 MiB gets 413", async () => {
  const res = await fetch(`${base}/v1/notes`, { method: "POST", headers: auth, body: "a".repeat(1024 * 1024 + 1) });
  assert.equal(res.status, 413);
});

import assert from "node:assert/strict";
import { mock, test } from "node:test";

interface Broker { post(text: string): Promise<void> }
const postProgress = async (broker: Broker, text: string): Promise<string> => {
  await broker.post(text.slice(0, 400)); // keep updates short
  return "posted";
};

test("postProgress sends the text to the broker once", async () => {
  const post = mock.fn(async (_text: string) => {}); // a fake broker method that records its calls
  assert.equal(await postProgress({ post }, "step 2 done"), "posted");
  assert.equal(post.mock.callCount(), 1);
  assert.deepEqual(post.mock.calls[0]?.arguments, ["step 2 done"]);
});

import { CreateTagsCommand, EC2Client } from "@aws-sdk/client-ec2";

export const tagForRun = async (ec2: EC2Client, instanceId: string, runId: string): Promise<void> => {
  await ec2.send(new CreateTagsCommand({
    Resources: [instanceId],
    Tags: [{ Key: "ai-agents:run-id", Value: runId }],
  }));
};

import assert from "node:assert/strict";
import { test } from "node:test";
import { CreateTagsCommand, EC2Client } from "@aws-sdk/client-ec2";
import { mockClient } from "aws-sdk-client-mock";
import { tagForRun } from "../src/tags.js";

const ec2Mock = mockClient(EC2Client); // every EC2Client now answers from this fake, not AWS

test("tagForRun tags the VM with its run id", async () => {
  ec2Mock.reset();
  ec2Mock.on(CreateTagsCommand).resolves({});
  await tagForRun(new EC2Client({ region: "us-east-1" }), "i-0abc", "run-7");
  const calls = ec2Mock.commandCalls(CreateTagsCommand);
  assert.equal(calls.length, 1);
  assert.deepEqual(calls[0]?.args[0].input.Tags, [{ Key: "ai-agents:run-id", Value: "run-7" }]);
});

test("an AWS error reaches the caller", async () => {
  ec2Mock.reset();
  ec2Mock.on(CreateTagsCommand).rejects(new Error("UnauthorizedOperation"));
  await assert.rejects(tagForRun(new EC2Client({ region: "us-east-1" }), "i-0abc", "run-7"), /UnauthorizedOperation/);
});
